head.b:skin:
/*
  Theme Name: SynFusion Blogger Premium Theme
  Author: SynFusion Agency
  Tagline: We Build. We Innovate. We Scale.
*/
body {
  margin: 0;
  padding: 0;
  background-color: #ffffff;
  color: #172033;
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  // Set current copyright year
  var yearEl = document.getElementById('copyrightYear');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  // Mobile Menu Toggle
  var mobileToggle = document.getElementById('mobileToggle');
  var navLinks = document.getElementById('navLinks');
  var mobileContactBar = document.getElementById('mobileContactBar');

  if (mobileToggle && navLinks) {
    mobileToggle.addEventListener('click', function() {
      var isExpanded = navLinks.classList.toggle('active');
      if (mobileContactBar) {
        mobileContactBar.style.display = isExpanded ? 'none' : 'flex';
      }
    });

    // Close menu on link click
    var links = navLinks.querySelectorAll('a');
    links.forEach(function(link) {
      link.addEventListener('click', function() {
        navLinks.classList.remove('active');
        if (mobileContactBar) {
          mobileContactBar.style.display = 'flex';
        }
      });
    });
  }

  // FAQ Accordion Toggle Function
  window.toggleFAQ = function(element) {
    var faqItem = element.parentElement;
    var isActive = faqItem.classList.contains('active');

    // Close all other FAQ items
    var allItems = document.querySelectorAll('.faq-item');
    allItems.forEach(function(item) {
      item.classList.remove('active');
    });

    if (!isActive) {
      faqItem.classList.add('active');
    }
  };

  // Portfolio Filtering
  var filterBtns = document.querySelectorAll('.filter-btn');
  var portfolioCards = document.querySelectorAll('.portfolio-card');

  filterBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      filterBtns.forEach(function(b) { b.classList.remove('active'); });
      this.classList.add('active');

      var filterVal = this.getAttribute('data-filter');

      portfolioCards.forEach(function(card) {
        var cat = card.getAttribute('data-category');
        if (filterVal === 'all' || filterVal === cat) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    });
  });

  // Scroll Reveal Animation via IntersectionObserver
  if ('IntersectionObserver' in window) {
    var observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.1
    };

    var observer = new IntersectionObserver(function(entries, obs) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
          obs.unobserve(entry.target);
        }
      });
    }, observerOptions);

    var revealElements = document.querySelectorAll('.reveal');
    revealElements.forEach(function(el) {
      observer.observe(el);
    });
  } else {
    // Fallback for older browsers
    var revealElements = document.querySelectorAll('.reveal');
    revealElements.forEach(function(el) {
      el.classList.add('active');
    });
  }

  // Contact Form Submission Handler
  window.handleContactSubmit = function(event) {
    event.preventDefault();
    var name = document.getElementById('contactName').value;
    var email = document.getElementById('contactEmail').value;
    var service = document.getElementById('contactService').value;
    var message = document.getElementById('contactMessage').value;
    var statusEl = document.getElementById('formStatusMessage');

    if (!name || !email || !service || !message) {
      if (statusEl) {
        statusEl.style.display = 'block';
        statusEl.style.color = '#E94B35';
        statusEl.textContent = 'Please fill in all required fields.';
      }
      return;
    }

    // Redirect to WhatsApp with filled message pre-populated
    var encodedMsg = encodeURIComponent(
      "Hi SynFusion Team,\n\nName: " + name +
      "\nEmail: " + email +
      "\nService: " + service +
      "\nProject Details: " + message
    );
    var waUrl = "https://wa.me/919334603912?text=" + encodedMsg;

    if (statusEl) {
      statusEl.style.display = 'block';
      statusEl.style.color = '#25D366';
      statusEl.textContent = 'Redirecting to WhatsApp with your inquiry...';
    }

    setTimeout(function() {
      window.open(waUrl, '_blank');
    }, 1000);
  };
});
//
